export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith('/api/releases')||url.pathname.startsWith('/play/'))return new Response('此功能已停用',{status:410,headers:{'Cache-Control':'no-store','Content-Type':'text/plain;charset=utf-8'}});if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const path=url.pathname==='/'?'/index.html':url.pathname,item=assets[path];if(!item)return new Response('Not found',{status:404});return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(item.data),c=>c.charCodeAt(0)),{headers:{'Content-Type':item.type,'Cache-Control':path.endsWith('.html')?'no-cache':'public,max-age=300','X-Content-Type-Options':'nosniff'}})}};
